// Copies the checker's data.js (the exact file the web page uses) into src/data.js
// and adds an export line so the Worker can import it. Run: npm run sync-data
import { readFileSync, writeFileSync } from "node:fs";
const src = process.argv[2] || "../networth-by-age/data.js";
const body = readFileSync(src, "utf8");
writeFileSync("src/data.js",
  "// GENERATED by scripts/sync-data.mjs from rogueiq/networth-by-age/data.js. Do not edit by hand.\n" +
  body + "\nexport { SCF_DATA, SCF_FILTERS };\n");
console.log("synced", src);
